import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"MiniMax Agent cookbook","description":"Read this after you can sign in. Each recipe solves one job and only uses steps that exist on an official page.","frontmatter":{"title":"MiniMax Agent cookbook","description":"Read this after you can sign in. Each recipe solves one job and only uses steps that exist on an official page.","domain":"product","tags":["coding-agent"],"role":"cookbook"},"headers":[],"relativePath":"products/minimax-agent/minimax-agent-cookbook.md","filePath":"products/minimax-agent/minimax-agent-cookbook.md","lastUpdated":1787107158000}'),i={name:"products/minimax-agent/minimax-agent-cookbook.md"};function r(s,e,l,d,h,p){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="minimax-agent-cookbook" tabindex="-1">MiniMax Agent cookbook <a class="header-anchor" href="#minimax-agent-cookbook" aria-label="Permalink to &quot;MiniMax Agent cookbook&quot;">​</a></h1><p>For readers who already have <a href="https://agent.minimax.io/" target="_blank" rel="noreferrer">agent.minimax.io</a> open. Each recipe: goal, steps, pitfall.</p><p>Setup and mode choice live in the <a href="./minimax-agent.html">tutorial</a>. This page does not repeat them.</p><h2 id="_1-a-sourced-research-report" tabindex="-1">1. A sourced research report <a class="header-anchor" href="#_1-a-sourced-research-report" aria-label="Permalink to &quot;1. A sourced research report&quot;">​</a></h2><p><strong>Goal:</strong> Markdown / PDF a coworker can reuse, not a chat log.</p><p><strong>When:</strong> Pro. Turn on Agent Team if sources must be checked in parallel.</p><p><strong>Steps:</strong></p><ol><li>Switch to Pro.</li><li>Put scope, banned sources, and output format in the first sentence.</li><li>Require an official URL after every claim.</li><li>If you also need HTML / slides, ask for both in that same message.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Using 2026 official pages only, document what MiniMax Agent can and cannot do.</span></span>
<span class="line"><span>Allowed hosts: minimaxi.com, minimax.io, agent.minimaxi.com, agent.minimax.io.</span></span>
<span class="line"><span>Banned: review blogs, social screenshots, scrapers.</span></span>
<span class="line"><span>Deliver a Markdown report. Every claim needs a source URL.</span></span></code></pre></div><p><strong>Pitfall:</strong> A single agent often stops halfway to &quot;report progress.&quot; The <a href="https://agent.minimaxi.com/docs/techblog/agent-team.md" target="_blank" rel="noreferrer">Agent Team</a> article calls this context anxiety. Write &quot;do not stop before the acceptance checks pass,&quot; or turn Team on.</p><h2 id="_2-slides-a-report-or-a-site-—-not-just-prose" tabindex="-1">2. Slides, a report, or a site — not just prose <a class="header-anchor" href="#_2-slides-a-report-or-a-site-—-not-just-prose" aria-label="Permalink to &quot;2. Slides, a report, or a site — not just prose&quot;">​</a></h2><p><strong>Goal:</strong> A downloadable deck, document, or openable page.</p><p><strong>Sources:</strong> The <a href="https://www.minimaxi.com/en/news/minimax-m2" target="_blank" rel="noreferrer">M2 post</a> lists PPT, reports, and web development under Pro. The <a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">launch post</a> showed audio tutorials and front-end animation pages.</p><p><strong>Steps:</strong></p><ol><li>Pro.</li><li>Name page count, audience, and format (HTML / PDF / PPTX / DOCX).</li><li>Ask for an outline first. The Team article splits office docs into Planner → Writer → Formatter → Evaluator.</li><li>For a fixed layout, check the <a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">skill marketplace</a> for a deck / DOCX / PowerPoint skill.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Write an 8-slide product intro for frontend engineers.</span></span>
<span class="line"><span>They already use Cursor and have never opened MiniMax Agent.</span></span>
<span class="line"><span>Give an outline first. After I confirm, generate HTML slides and a PDF export.</span></span>
<span class="line"><span>Do not include MiniMax Code install steps.</span></span></code></pre></div><p><strong>Pitfall:</strong> Do not run this in Lightning. Official copy puts it on Pro.</p><h2 id="_3-decide-whether-agent-team-is-worth-it" tabindex="-1">3. Decide whether Agent Team is worth it <a class="header-anchor" href="#_3-decide-whether-agent-team-is-worth-it" aria-label="Permalink to &quot;3. Decide whether Agent Team is worth it&quot;">​</a></h2><p><strong>Goal:</strong> Skip a wasted &quot;the single agent finished writing but nothing is shippable&quot; loop.</p><table tabindex="0"><thead><tr><th>Signal</th><th>Action</th></tr></thead><tbody><tr><td>You want one answer</td><td>No Team. Lightning is enough</td></tr><tr><td>Multi-source research + verify + synthesize</td><td>Team on</td></tr><tr><td>IM task, humans will not wait for the final file</td><td>Team on. Officially the lead replies immediately</td></tr><tr><td>Typo / one sentence</td><td>Off. Officially cheaper as a single agent</td></tr></tbody></table><p><strong>Steps:</strong> Turn on <strong>Agent Team</strong> on the home page, then send one goal. Do not pack three unrelated epics into one message.</p><p><strong>Pitfall:</strong> Team has handoff cost. The official article names handoff, sharing, and aggregation as new costs. A vague goal makes Worker and Verifier spin.</p><h2 id="_4-install-a-skill-before-repeating-the-same-job" tabindex="-1">4. Install a skill before repeating the same job <a class="header-anchor" href="#_4-install-a-skill-before-repeating-the-same-job" aria-label="Permalink to &quot;4. Install a skill before repeating the same job&quot;">​</a></h2><p><strong>Goal:</strong> The second similar deliverable should not start from a blank prompt.</p><p><strong>Steps:</strong></p><ol><li>Open <a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">skills</a>.</li><li>Search by job type (deck, research report, Excel, landing page).</li><li>Install, then refer to that skill in the next task.</li><li>If the market has nothing, but you have already run the flow twice, create a skill or import from GitHub. Both are in the official marketplace copy.</li></ol><p><strong>Pitfalls:</strong></p><ul><li>The catalog and use counts move. Do not treat a screenshot in this repo as the index.</li><li>The Code plugin marketplace (finance data, company lookup, Office, Notion, …) is documented in desktop release notes, not in this recipe.</li></ul><h2 id="_5-switch-products-instead-of-forcing-the-web-agent" tabindex="-1">5. Switch products instead of forcing the web Agent <a class="header-anchor" href="#_5-switch-products-instead-of-forcing-the-web-agent" aria-label="Permalink to &quot;5. Switch products instead of forcing the web Agent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You actually want</th><th>Go here</th><th>Do not</th></tr></thead><tbody><tr><td>Local repo, terminal, diffs, git</td><td><a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">MiniMax Code</a></td><td>Pretend the web Agent has a workspace panel</td></tr><tr><td>One video</td><td><a href="https://hailuoai.com/" target="_blank" rel="noreferrer">Hailuo</a></td><td>Detour through Agent &quot;because it can generate video&quot;</td></tr><tr><td>Voice / music</td><td><a href="https://www.minimaxi.com/audio" target="_blank" rel="noreferrer">Audio</a></td><td>Treat Audio as an Agent mode</td></tr><tr><td>Roleplay</td><td><a href="https://www.xingyeai.com/" target="_blank" rel="noreferrer">Xingye</a> / <a href="https://www.talkie-ai.com/" target="_blank" rel="noreferrer">Talkie</a></td><td>Write a companion app up as a workbench</td></tr><tr><td>Storyboard-to-film canvas</td><td><a href="https://design.minimaxi.com/" target="_blank" rel="noreferrer">Design</a></td><td>Treat the old Hub name as Agent</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Learning map</a></li><li><a href="./minimax-agent.html">Tutorial</a></li><li><a href="./minimax-agent-cheatsheet.html">Cheatsheet</a></li><li><a href="./minimax-agent-glossary.html">Glossary</a></li></ul>`,32)])])}const b=t(i,[["render",r]]);export{u as __pageData,b as default};
